CREATE OR REPLACE FUNCTION public.trg_validar_cartones_inscripcion()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  max_cartones integer;
  carton_num bigint;
begin
  max_cartones := public.fn_total_cartones_actual();

  if max_cartones < 1 then
    raise exception 'total_cartones no está configurado correctamente';
  end if;

  if new.cartones is null then
    return new;
  end if;

  foreach carton_num in array new.cartones loop
    if carton_num is null or carton_num < 1 or carton_num > max_cartones then
      raise exception 'Inscripción tiene cartón % fuera de rango. Permitido: 1 a %',
        carton_num,
        max_cartones;
    end if;
  end loop;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_validar_numero_carton()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  max_cartones integer;
begin
  max_cartones := public.fn_total_cartones_actual();

  if max_cartones < 1 then
    raise exception 'total_cartones no está configurado correctamente';
  end if;

  if new.numero is null or new.numero < 1 or new.numero > max_cartones then
    raise exception 'Cartón % fuera de rango. Permitido: 1 a %', new.numero, max_cartones;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_validar_total_cartones_config()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  nuevo_total integer;
  mayor_en_cartones integer;
  mayor_en_inscripciones integer;
  mayor_usado integer;
begin
  if new.clave <> 'total_cartones' then
    return new;
  end if;

  if new.valore is null or new.valore !~ '^[0-9]+$' or new.valore::integer < 1 then
    raise exception 'total_cartones debe ser un número entero mayor a 0';
  end if;

  nuevo_total := new.valore::integer;

  select coalesce(max(numero), 0)::integer
  into mayor_en_cartones
  from public.cartones;

  select coalesce(max(x.carton::integer), 0)
  into mayor_en_inscripciones
  from public.inscripciones i
  cross join lateral unnest(i.cartones) as x(carton);

  mayor_usado := greatest(mayor_en_cartones, mayor_en_inscripciones);

  if nuevo_total < mayor_usado then
    raise exception 
      'No puedes configurar total_cartones en %, porque ya existe/usaste el cartón %',
      nuevo_total,
      mayor_usado;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.trigger_limpiar_expiradas()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  PERFORM limpiar_reservas_expiradas();
  RETURN NEW;
END;
$function$

